using System;
using System.Text;
using System.Runtime.InteropServices;
using System.Collections.Generic;
public class WinEnum {
  [DllImport("user32.dll")] static extern bool EnumWindows(EnumWindowsProc cb, IntPtr lp);
  [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
  [DllImport("user32.dll")] static extern int GetWindowText(IntPtr h, StringBuilder sb, int max);
  [DllImport("user32.dll")] static extern int GetClassName(IntPtr h, StringBuilder sb, int max);
  [DllImport("user32.dll")] static extern bool IsWindowVisible(IntPtr h);
  delegate bool EnumWindowsProc(IntPtr h, IntPtr lp);
  public static List<string> GetWindowsForPid(uint targetPid) {
    var result = new List<string>();
    EnumWindows((h, lp) => {
      uint pid; GetWindowThreadProcessId(h, out pid);
      if (pid == targetPid) {
        var t = new StringBuilder(256); GetWindowText(h, t, 256);
        var c = new StringBuilder(256); GetClassName(h, c, 256);
        result.Add(string.Format("vis={0} class='{1}' title='{2}'", IsWindowVisible(h), c, t));
      }
      return true;
    }, IntPtr.Zero);
    return result;
  }
}
'@; $gameDir = "C:\Users\olive_\OneDrive\Desktop\GT4_S4N_4NDR34S"; $p = Start-Process -FilePath "$gameDir\gta_sa.exe" -WorkingDirectory $gameDir -PassThru; $sw = [Diagnostics.Stopwatch]::StartNew(); while (-not $p.HasExited -and $sw.Elapsed.TotalSeconds -lt 20) { $w = [WinEnum]::GetWindowsForPid($p.Id); if ($w.Count -gt 0) { "[{0:F1}s] {1}" -f $sw.Elapsed.TotalSeconds, ($w -join ' | ') }; Start-Sleep -Milliseconds 400 }; if ($p.HasExited) { "[{0:F1}s] PROCESS EXITED code={1}" -f $sw.Elapsed.TotalSeconds, $p.ExitCode } else { "still alive after 20s"; Stop-Process -Id $p.Id -Force -Confirm:$false }

