using System;
using System.Text;
using System.Runtime.InteropServices;
using System.Collections.Generic;
public class ModList {
  [DllImport("kernel32.dll")] static extern IntPtr OpenProcess(uint acc, bool inh, int pid);
  [DllImport("psapi.dll")] static extern bool EnumProcessModulesEx(IntPtr h, [Out] IntPtr[] mods, uint cb, out uint needed, uint filter);
  [DllImport("psapi.dll", CharSet=CharSet.Unicode)] static extern uint GetModuleFileNameExW(IntPtr h, IntPtr mod, StringBuilder name, uint size);
  [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr h);
  public static List<string> Get(int pid) {
    var r = new List<string>();
    IntPtr h = OpenProcess(0x0410, false, pid);
    if (h == IntPtr.Zero) { r.Add("OpenProcess failed"); return r; }
    var mods = new IntPtr[2048]; uint needed;
    if (EnumProcessModulesEx(h, mods, (uint)(mods.Length * IntPtr.Size), out needed, 3)) {
      int count = (int)(needed / IntPtr.Size);
      for (int i = 0; i < count; i++) {
        var sb = new StringBuilder(512);
        GetModuleFileNameExW(h, mods[i], sb, 512);
        r.Add(sb.ToString());
      }
    } else r.Add("EnumProcessModulesEx failed");
    CloseHandle(h);
    return r;
